/** Educational left-leaning red-black tree with invariant checker. */
class TeachingRedBlack { static class N{int k;boolean red=true;N l,r;N(int k){this.k=k;}} N root; boolean red(N n){return n!=null&&n.red;} N left(N h){N x=h.r;h.r=x.l;x.l=h;x.red=h.red;h.red=true;return x;} N right(N h){N x=h.l;h.l=x.r;x.r=h;x.red=h.red;h.red=true;return x;} void flip(N h){h.red=!h.red;h.l.red=!h.l.red;h.r.red=!h.r.red;} void insert(int k){root=ins(root,k);root.red=false;} N ins(N h,int k){if(h==null)return new N(k);if(k<h.k)h.l=ins(h.l,k);else if(k>h.k)h.r=ins(h.r,k);if(red(h.r)&&!red(h.l))h=left(h);if(red(h.l)&&red(h.l.l))h=right(h);if(red(h.l)&&red(h.r))flip(h);return h;} int blackHeight(N n){if(n==null)return 1;int a=blackHeight(n.l),b=blackHeight(n.r);if(a!=b)throw new IllegalStateException("black height mismatch");if(red(n)&&(red(n.l)||red(n.r)))throw new IllegalStateException("double red");return a+(red(n)?0:1);} boolean ok(){return root==null||(!root.red&&blackHeight(root)>0);} static void deletionTrace(){System.out.println("Deletion concept trace: double black -> inspect sibling -> recolor or rotate -> propagate if needed.");} }
